249	  // Return the ULP (units-in-the-last-place) difference between the
250	  // stored MPFR and a floating point number.
251	  //
252	  // We define ULP difference as follows:
253	  //   If exponents of this value and the |input| are same, then:
254	  //     ULP(this_value, input) = abs(this_value - input) / eps(input)
255	  //   else:
256	  //     max = max(abs(this_value), abs(input))
257	  //     min = min(abs(this_value), abs(input))
258	  //     maxExponent = exponent(max)
259	  //     ULP(this_value, input) = (max - 2^maxExponent) / eps(max) +
260	  //                              (2^maxExponent - min) / eps(min)
261	  //
262	  // Remarks:
263	  // 1. A ULP of 0.0 will imply that the value is correctly rounded.
264	  // 2. We expect that this value and the value to be compared (the [input]
265	  //    argument) are reasonable close, and we will provide an upper bound
266	  //    of ULP value for testing.  Morever, most of the fractional parts of
267	  //    ULP value do not matter much, so using double as the return type
268	  //    should be good enough.
269	  // 3. For close enough values (values which don't diff in their exponent by
270	  //    not more than 1), a ULP difference of N indicates a bit distance
271	  //    of N between this number and [input].
272	  // 4. A values of +0.0 and -0.0 are treated as equal.
273	  template <typename T>
274	  cpp::enable_if_t<cpp::is_floating_point_v<T>, MPFRNumber>
275	  ulp_as_mpfr_number(T input) {
276	    T thisAsT = as<T>();
277	    if (thisAsT == input)
278	      return MPFRNumber(0.0);
279	
280	    if (is_nan()) {
281	      if (FPBits<T>(input).is_nan())
282	        return MPFRNumber(0.0);
283	      return MPFRNumber(FPBits<T>::inf().get_val());
284	    }
285	
286	    int thisExponent = FPBits<T>(thisAsT).get_exponent();
287	    int inputExponent = FPBits<T>(input).get_exponent();
288	    // Adjust the exponents for denormal numbers.
289	    if (FPBits<T>(thisAsT).is_subnormal())
290	      ++thisExponent;
291	    if (FPBits<T>(input).is_subnormal())
292	      ++inputExponent;
293	
294	    if (thisAsT * input < 0 || thisExponent == inputExponent) {
295	      MPFRNumber inputMPFR(input);
296	      mpfr_sub(inputMPFR.value, value, inputMPFR.value, MPFR_RNDN);
297	      mpfr_abs(inputMPFR.value, inputMPFR.value, MPFR_RNDN);
298	      mpfr_mul_2si(inputMPFR.value, inputMPFR.value,
299	                   -thisExponent + FPBits<T>::FRACTION_LEN, MPFR_RNDN);
300	      return inputMPFR;
301	    }
302	
303	    // If the control reaches here, it means that this number and input are
304	    // of the same sign but different exponent. In such a case, ULP error is
305	    // calculated as sum of two parts.
306	    thisAsT = FPBits<T>(thisAsT).abs().get_val();
307	    input = FPBits<T>(input).abs().get_val();
308	    T min = thisAsT > input ? input : thisAsT;
309	    T max = thisAsT > input ? thisAsT : input;
310	    int minExponent = FPBits<T>(min).get_exponent();
311	    int maxExponent = FPBits<T>(max).get_exponent();
312	    // Adjust the exponents for denormal numbers.
313	    if (FPBits<T>(min).is_subnormal())
314	      ++minExponent;
315	    if (FPBits<T>(max).is_subnormal())
316	      ++maxExponent;
317	
318	    MPFRNumber minMPFR(min);
319	    MPFRNumber maxMPFR(max);
320	
321	    MPFRNumber pivot(uint32_t(1));
322	    mpfr_mul_2si(pivot.value, pivot.value, maxExponent, MPFR_RNDN);
323	
324	    mpfr_sub(minMPFR.value, pivot.value, minMPFR.value, MPFR_RNDN);
325	    mpfr_mul_2si(minMPFR.value, minMPFR.value,
326	                 -minExponent + FPBits<T>::FRACTION_LEN, MPFR_RNDN);
327	
328	    mpfr_sub(maxMPFR.value, maxMPFR.value, pivot.value, MPFR_RNDN);
329	    mpfr_mul_2si(maxMPFR.value, maxMPFR.value,
330	                 -maxExponent + FPBits<T>::FRACTION_LEN, MPFR_RNDN);
331	
332	    mpfr_add(minMPFR.value, minMPFR.value, maxMPFR.value, MPFR_RNDN);
333	    return minMPFR;
334	  }
335	
336	  template <typename T>
337	  cpp::enable_if_t<cpp::is_floating_point_v<T>, cpp::string>
338	  ulp_as_string(T input) {
339	    MPFRNumber num = ulp_as_mpfr_number(input);
340	    return num.str();
341	  }
342	
343	  template <typename T>
344	  cpp::enable_if_t<cpp::is_floating_point_v<T>, double> ulp(T input) {
345	    MPFRNumber num = ulp_as_mpfr_number(input);
346	    return num.as<double>();
347	  }
348	};
