138	template <typename InputType>
139	cpp::enable_if_t<cpp::is_floating_point_v<InputType>, MPFRNumber>
140	binary_operation_one_output(Operation op, InputType x, InputType y,
141	                            unsigned int precision, RoundingMode rounding) {
142	  MPFRNumber inputX(x, precision, rounding);
143	  MPFRNumber inputY(y, precision, rounding);
144	  switch (op) {
145	  case Operation::Add:
146	    return inputX.add(inputY);
147	  case Operation::Atan2:
148	    return inputX.atan2(inputY);
149	  case Operation::Div:
150	    return inputX.div(inputY);
151	  case Operation::Fmod:
152	    return inputX.fmod(inputY);
153	  case Operation::Hypot:
154	    return inputX.hypot(inputY);
155	  case Operation::Mul:
156	    return inputX.mul(inputY);
157	  case Operation::Pow:
158	    return inputX.pow(inputY);
159	  case Operation::Sub:
160	    return inputX.sub(inputY);
161	  default:
162	    __builtin_unreachable();
163	  }
164	}
