167	cpp::enable_if_t<cpp::is_floating_point_v<InputType>, MPFRNumber>
168	binary_operation_two_outputs(Operation op, InputType x, InputType y,
169	                             int &output, unsigned int precision,
170	                             RoundingMode rounding) {
171	  MPFRNumber inputX(x, precision, rounding);
