181	template <typename InputType>
182	cpp::enable_if_t<cpp::is_floating_point_v<InputType>, MPFRNumber>
183	ternary_operation_one_output(Operation op, InputType x, InputType y,
184	                             InputType z, unsigned int precision,
185	                             RoundingMode rounding) {
186	  // For FMA function, we just need to compare with the mpfr_fma with the same
187	  // precision as InputType.  Using higher precision as the intermediate results
188	  // to compare might incorrectly fail due to double-rounding errors.
189	  MPFRNumber inputX(x, precision, rounding);
190	  MPFRNumber inputY(y, precision, rounding);
191	  MPFRNumber inputZ(z, precision, rounding);
192	  switch (op) {
193	  case Operation::Fma:
194	    return inputX.fma(inputY, inputZ);
195	  default:
196	    __builtin_unreachable();
197	  }
198	}
