200	// Remark: For all the explain_*_error functions, we will use std::stringstream
201	// to build the complete error messages before sending it to the outstream `OS`
202	// once at the end.  This will stop the error messages from interleaving when
203	// the tests are running concurrently.
204	template <typename InputType, typename OutputType>
205	void explain_unary_operation_single_output_error(Operation op, InputType input,
206	                                                 OutputType matchValue,
207	                                                 double ulp_tolerance,
208	                                                 RoundingMode rounding) {
209	  unsigned int precision = get_precision<InputType>(ulp_tolerance);
210	  MPFRNumber mpfrInput(input, precision);
211	  MPFRNumber mpfr_result;
212	  mpfr_result = unary_operation(op, input, precision, rounding);
213	  MPFRNumber mpfrMatchValue(matchValue);
214	  cpp::array<char, 1024> msg_buf;
215	  cpp::StringStream msg(msg_buf);
216	  msg << "Match value not within tolerance value of MPFR result:\n"
217	      << "  Input decimal: " << mpfrInput.str() << '\n';
218	  msg << "     Input bits: " << str(FPBits<InputType>(input)) << '\n';
219	  msg << '\n' << "  Match decimal: " << mpfrMatchValue.str() << '\n';
220	  msg << "     Match bits: " << str(FPBits<OutputType>(matchValue)) << '\n';
221	  msg << '\n' << "    MPFR result: " << mpfr_result.str() << '\n';
222	  msg << "   MPFR rounded: "
223	      << str(FPBits<OutputType>(mpfr_result.as<OutputType>())) << '\n';
224	  msg << '\n';
225	  msg << "      ULP error: " << mpfr_result.ulp_as_mpfr_number(matchValue).str()
226	      << '\n';
227	  if (msg.overflow())
228	    __builtin_unreachable();
229	  tlog << msg.str();
230	}
