292	void explain_unary_operation_two_outputs_error(
293	    Operation op, T input, const BinaryOutput<T> &libc_result,
294	    double ulp_tolerance, RoundingMode rounding) {
295	  unsigned int precision = get_precision<T>(ulp_tolerance);
296	  MPFRNumber mpfrInput(input, precision);
297	  int mpfrIntResult;
298	  MPFRNumber mpfr_result = unary_operation_two_outputs(op, input, mpfrIntResult,
299	                                                       precision, rounding);
300	
301	  if (mpfrIntResult != libc_result.i) {
302	    tlog << "MPFR integral result: " << mpfrIntResult << '\n'
303	         << "Libc integral result: " << libc_result.i << '\n';
304	  } else {
305	    tlog << "Integral result from libc matches integral result from MPFR.\n";
306	  }
307	
308	  MPFRNumber mpfrMatchValue(libc_result.f);
309	  tlog
310	      << "Libc floating point result is not within tolerance value of the MPFR "
311	      << "result.\n\n";
312	
313	  tlog << "            Input decimal: " << mpfrInput.str() << "\n\n";
314	
315	  tlog << "Libc floating point value: " << mpfrMatchValue.str() << '\n';
316	  tlog << " Libc floating point bits: " << str(FPBits<T>(libc_result.f))
317	       << '\n';
318	  tlog << "\n\n";
319	
320	  tlog << "              MPFR result: " << mpfr_result.str() << '\n';
321	  tlog << "             MPFR rounded: " << str(FPBits<T>(mpfr_result.as<T>()))
322	       << '\n';
323	  tlog << '\n'
324	       << "                ULP error: "
325	       << mpfr_result.ulp_as_mpfr_number(libc_result.f).str() << '\n';
326	}
