448	template <typename InputType, typename OutputType>
449	void explain_ternary_operation_one_output_error(
450	    Operation op, const TernaryInput<InputType> &input, OutputType libc_result,
451	    double ulp_tolerance, RoundingMode rounding) {
452	  unsigned int precision = get_precision<InputType>(ulp_tolerance);
453	  MPFRNumber mpfrX(input.x, precision);
454	  MPFRNumber mpfrY(input.y, precision);
455	  MPFRNumber mpfrZ(input.z, precision);
456	  FPBits<InputType> xbits(input.x);
457	  FPBits<InputType> ybits(input.y);
458	  FPBits<InputType> zbits(input.z);
459	  MPFRNumber mpfr_result = ternary_operation_one_output(
460	      op, input.x, input.y, input.z, precision, rounding);
461	  MPFRNumber mpfrMatchValue(libc_result);
462	
463	  tlog << "Input decimal: x: " << mpfrX.str() << " y: " << mpfrY.str()
464	       << " z: " << mpfrZ.str() << '\n';
465	  tlog << " First input bits: " << str(FPBits<InputType>(input.x)) << '\n';
466	  tlog << "Second input bits: " << str(FPBits<InputType>(input.y)) << '\n';
467	  tlog << " Third input bits: " << str(FPBits<InputType>(input.z)) << '\n';
468	
469	  tlog << "Libc result: " << mpfrMatchValue.str() << '\n'
470	       << "MPFR result: " << mpfr_result.str() << '\n';
471	  tlog << "Libc floating point result bits: "
472	       << str(FPBits<OutputType>(libc_result)) << '\n';
473	  tlog << "              MPFR rounded bits: "
474	       << str(FPBits<OutputType>(mpfr_result.as<OutputType>())) << '\n';
475	  tlog << "ULP error: " << mpfr_result.ulp_as_mpfr_number(libc_result).str()
476	       << '\n';
477	}
